/** A dependency cycle found while walking the graph. */
export class CycleError extends Error {
  /** @param {string[]} names - the cycle, from the re-entered task back to itself. */
  constructor(names) {
    super(`cycle: ${names.join(' -> ')}`)
    this.name = 'CycleError'
    this.names = names
  }
}

/**
 * The first cycle a depth-first search finds, starting from each task in
 * ascending name order and walking each task's dependencies in ascending
 * name order.
 * @param {Map<string, {needs: string[]}>} tasks - the parsed tasks.
 * @returns {string[]|null} the cycle, from the re-entered task back to itself, or null.
 */
function findCycle(tasks) {
