{"file_path":"src/plan.js","content":"/** What the graph would have to rerun against a digest snapshot. */

import { existsSync, readFileSync } from 'node:fs'
import { digestBytes } from './digest.js'

/**
 * The lines `plan` prints for the given run order, and the totals it counts.
 * @param {Map<string, {needs: string[], reads: string[], writes: string[]}>} tasks - the parsed tasks.
 * @param {string[]} names - the task names in run order.
 * @param {Map<string, string>} digests - the digest recorded for each path in the snapshot.
 * @returns {{lines: string[], run: number, skip: number}} the report.
 */
export function plan(tasks, names, digests) {
  const runs = new Map()
  const lines = []
  let run = 0
  let skip = 0
  for (const name of names) {
    const task = tasks.get(name)
    const watched = [...new Set([...task.reads, ...task.writes])].sort()
    let reason = null
    for (const path of watched) {
      if (!digests.has(path)) {
        reason = `new ${path}`
        break
      }
      if (!existsSync(path)) {
        reason = `missing ${path}`
        break
      }
      if (digestBytes(readFileSync(path)) !== digests.get(path)) {
        reason = `changed ${path}`
        break
      }
    }
    if (reason === null) {
      for (const dep of [...task.needs].sort()) {
        if (runs.get(dep)) {
          reason = `needs ${dep}`
          break
        }
      }
    }
    if (reason === null) {
      runs.set(name, false)
      skip += 1
      lines.push(`skip ${name}`)
    } else {
      runs.set(name, true)
      run += 1
      lines.push(`run ${name} ${reason}`)
    }
  }
  return { lines, run, skip }
}
"}

